def max_value_on_paths(N, grid_values):
    grid = [[0 for _ in range(N)] for _ in range(N)]
    for x, y, value in grid_values:
        if value:
            grid[x][y] = value

    def dfs(x, y, prev_path, max_sum):
        if x == N or y == N:
            return max_sum
        max_value = 0
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and grid[nx][ny] > prev_path:
                max_value = max(max_value, dfs(nx, ny, grid[nx][ny], max_sum + grid[nx][ny]))
        return max_value

    max_sum = 0
    for i in range(N):
        for j in range(N):
            max_sum = max(max_sum, dfs(i, j, grid[i][j], grid[i][j]))
    return max_sum
```

