def max_value_on_paths(N, grid_values):
    n = N
    # Convert tuple list to a 2D array for easier manipulation
    grid = [list(x) for x in grid_values if x[0] != 0]

    # Initialize DP tables for each path
    dp_top2bot = [[0] * n for _ in range(n)]
    dp_bot2top = [[0] * n for _ in range(n)]

    # Forward path from top-left to bottom-right
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp_top2bot[i][j] = grid[i][j]
            elif i > 0:
                dp_top2bot[i][j] = max(dp_top2bot[i-1][j], grid[i][j]) + dp_top2bot[i-1][j-1]
            elif j > 0:
                dp_top2bot[i][j] = max(dp_top2bot[i][j-1], grid[i][j]) + dp_top2bot[i-1][j-1]

    # Backward path from bottom-right to top-left
    for i in range(n-1, -1, -1):
        dp_bot2top[i][0] = grid[i][0]
        for j in range(1, n):
            if j == 0:
                dp_bot2top[i][j] = max(dp_bot2top[i+1][j], dp_bot2top[i][j-1]) + dp_bot2top[i][j+1]
            elif i < n-1:
                dp_bot2top[i][j] = max(dp_bot2top[i+1][j], dp_bot2top[i][j-1]) + dp_bot2top[i][j+1]
            elif j < n-1:
                dp_bot2top[i][j] = max(dp_bot2top[i][j-1], dp_bot2top[i+1][j]) + dp_bot2top[i][j+1]

    # Total path sum的最大值 is the sum of the paths passing through the bottom-right corner
    # The sum is the values collected on the forward path minus the value already counted once over
    # To avoid double-counting, we just sum the values on the forward and backward paths in sequence
    max_sum = sum(dp_top2bot[-1]) + sum(dp_bot2top[-1])

    return max_sum
```

