def cantor_numbering(N: int) -> str:
    if N <= 0:
        return "Error: N must be a positive integer."

    numerator = N - 1
    denominator = 2 * (N - 1) + 1
    if numerator >= denominator:
        numerator = denominator - (numerator - denominator)
        return f"{denominator}/{numerator}"
    else:
        return f"{numerator}/{denominator}"
