def cantor_numbering(N: int) -> str:
    def iterate(m: int, n: int) -> str:
        if m == 1:
            return f"{n}"
        else:
            divider = (m + n) // 2
            remainder = (m + n) % 2
            if remainder == 0:
                return f"{iterate(remainder, m)} / {iterate(divider, remainder)}"
            else:
                return f"{iterate(divider + remainder, n)} / {iterate(remainder, n)}"

    return iterate(N, (N + 1) // 2)
```

