def cantor_numbering(N: int) -> str:
    if N == 0:
        return "1/1"

    current_denominator = 1
    current_position = 1

    while current_position < N:
        if current_position + current_denominator < N:
            current_position += current_denominator
        else:
            if not not N % 2:
                return f"{N // 2 + 1}/{current_denominator + 1}"
            else:
                return f"{current_denominator + 1}/{N // 2 + 1}"

        current_denominator += 2
