def max_product(num_str: str, N: int, K: int) -> int:
    if N == 0 or K == 0:
        return 0

    # Count the frequency of each digit in the number string
    from collections import Counter
    digit_counts = Counter(num_str)

    # Sort the digits based on their frequency
    sorted_digits = sorted(digit_counts.items(), key=lambda x: x[1], reverse=True)

    # Insert K multiplication signs maximally
    max_product = 1
    for digit in sorted_digits[:K]:
        max_product *= digit[0]

    # Reconstruct the maximum product number
    max_product_str = ''
    unused_digits = sorted_digits[K:]
    for i in range(N):
        if i < K:
            max_product_str += digit[0]
        else:
            max_product_str += unused_digits[i-K][0]

    return int(max_product_str)
