def max_product(num_str: str, N: int, K: int) -> int:
    n = len(num_str)
    dp = [[0 for _ in range(K + 1)] for _ in range(n + 1)]
    prefix_sum = [0] * (n + 1)

    # Base case: If there are no multiplication signs, just take the product of all numbers
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] * int(num_str[i - 1])
        dp[i][0] = prefix_sum[i]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, K + 1):
            if i + j - 1 > N:
                continue
            if j == 1:
                dp[i + j][j] = prefix_sum[i] * prefix_sum[i + j]
            else:
                for x in range(i + 1, i + j + 1):
                    dp[i + j][j] = max(dp[i + j][j], dp[x][j - 1] * prefix_sum[i] * prefix_sum[x + 1])

    return dp[n][K]
```

