def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize variables to keep track of optimal aisle positions
    optimal_row = 0
    optimal_col = 0
    max_chatting_pairs = 0

