    for pair in chatting_pairs:
        if M - pair[1] < 2:
            D -= pair[1] - 1
            if D < 0:
                return 'Error: Not enough space for aisles', '0'
        if N - pair[2] < 2:
            D -= pair[2] - 1
            if D < 0:
                return 'Error: Not enough space for aisles', '0'

    # Minimize chat pairs by adding aisles in columns
    for col in range(N):
        col_pairs = [pair for pair in chatting_pairs if pair[2] == col]
        if col_pairs:
            max_col = max(pair[0] for pair in col_pairs)
            min_col = min(pair[1] for pair in col_pairs)
            if max_col - min_col >= 3 and col not in [optimal_row, optimal_col]:
                if D >= 3:
                    optimal_col = col
                    D -= 3
                else:
                    return 'Error: Not enough space for aisles', '0'

    # Return the optimal aisle positions
    return (str(optimal_row), str(optimal_col)) if optimal_col != 0 else ('full', 'full') if D > 0 else ('', '')
