def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c, shift):
        if c.islower():
            return chr((( ord(c) - ord('a') + shift) % 26) + ord('a'))
        elif c.isupper():
            return chr((( ord(c) - ord('A') + shift) % 26) + ord('A'))
        return c

    def decrypt_char(c):
        keyword = key[(key.index(c) - len(key)) % len(key)]
        shift_amount = ord(keyword) - ord('A')
        return shift_char(c, shift_amount)

    return ''.join(decrypt_char(c) for c in ciphertext)
