def mod_inverse(a, b):
    if a == 0:
        return None

    x = 0
    y = 1

    if b == 0:
        return None

    while a > 0:
        quotient = a // b
        a, b = b, a % b
        x, y = y, x - quotient * y

    if x < 0:
        x = (x + b) % b

    return x
```

