def next_permutation(perm: list) -> bool:
    N = len(perm)
    # Find the first number v that violates the monotonic non-decreasing property from the end of the list
    for i in range(N - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    # If no such number is found, the permutation is the last one
    else:
        return False

    # Find the smallest number in the remaining part of the list that is larger than v
    for k in range(N - 1, i, -1):
        if perm[k] > perm[i]:
            break

    # Swap v with the found number
    perm[i], perm[k] = perm[k], perm[i]

    # Reverse the order from the position i+1 to the end of the list
    perm[i + 1:] = perm[i + 1:][::-1]

    return True
```

