def minimum_students_to_leave(heights):
    # Finding the longest non-increasing subsequence (LIS)
    lis = []
    for h in heights:
        if not lis or h <= lis[-1]:
            lis.append(h)
        else:
            lis[bisect.bisect_left(lis, h)] = h

    # Converting LIS to a deque
    lis_deque = deque(lis)

    # Finding the longest non-decreasing subsequence (LDS)
    lds = []
    while lis_deque:
        h = lis_deque.pop()
        if not lds or h <= lds[-1]:
            lds.append(h)
        else:
            lds[bisect.bisect_left(lds, h)] = h

    # The difference between the lengths of LIS and LDS is the number of students that need to stay
    return len(heights) - len(lds)
