def hanoi_double_iterative(n: int) -> int:
    # Iterative approach to solve the double-disc Hanoi Tower problem
    if n % 2 == 0:
        initial_moves = 2 * (3 ** n - 3) + 2
    else:
        initial_moves = 2 * (3 ** (n // 2) - 3) + (n // 2) * (2 * (3 ** ((n // 2) - 1)) - 2)

    # Update the number of moves based on the height of the last move
    for i in range(n - 1):
        if i % 2 == 0:
            initial_moves += 2 * (3 ** (n // 2) - 3) + (i // 2) * (2 * (3 ** ((n // 2) - 1)) - 2)
        else:
            initial_moves += 2 * (3 ** (n // 2) - 3) + (i // 2) * (3 ** ((n // 2) - 1)) - 2

    return initial_moves
