def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14

    # Initialize the number of moves for n=1, n=2, and n=3
    moves = [2, 6, 14]

    # Compute the number of moves for n greater than 3 using recursion
    for i in range(4, n + 1):
        moves.append(4 * moves[i - 3] + 2)

    return moves[n]
